function patternGate(text, pattern) {
  const go = (i, j) => {
    if (j === pattern.length) return i === text.length;
    if (pattern[j] === '*') {
      for (let k = i; k <= text.length; k++) if (go(k, j + 1)) return true;
      return false;
    }
    return i < text.length && (pattern[j] === '?' || pattern[j] === text[i]) && go(i + 1, j + 1);
  };
  return go(0, 0);
}

function patternGate(text, pattern) {
  let ok = new Array(pattern.length + 1).fill(false);
  ok[0] = true;
  for (let j = 1; j <= pattern.length; j++) ok[j] = ok[j - 1] && pattern[j - 1] === '*';
  for (let i = 1; i <= text.length; i++) {
    const next = new Array(pattern.length + 1).fill(false);
    for (let j = 1; j <= pattern.length; j++) {
      const p = pattern[j - 1];
      if (p === '*') next[j] = next[j - 1] || ok[j];
      else next[j] = (p === '?' || p === text[i - 1]) && ok[j - 1];
    }
    ok = next;
  }
  return ok[pattern.length];
}
